import{_ as i,a,c as e,ac as n}from"./chunks/framework.BSuaGltH.js";const o=JSON.parse('{"title":"MySQL 起步与命令 SQL：连接、建库和基本读写","description":"用固定MySQL 8.4 LTS隔离实验理解客户端与服务端、字符集、NULL、事务和命令行。","frontmatter":{"title":"MySQL 起步与命令 SQL：连接、建库和基本读写","description":"用固定MySQL 8.4 LTS隔离实验理解客户端与服务端、字符集、NULL、事务和命令行。","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL 8.4 实践课程","summary":"用固定MySQL 8.4 LTS隔离实验理解客户端与服务端、字符集、NULL、事务和命令行。","status":"active","related":[{"title":"MySQL 操作与命令","link":"/middleware/mysql/plus/ecosystem/mysql-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 查询练习：筛选、NULL 与分页","link":"/middleware/mysql/query-exercises","kind":"应用实践","scope":"general","audience":"general"},{"title":"MySQL 查询语法与函数","link":"/middleware/mysql/plus/subjects/mysql-select-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"MySQL 建模与查询：约束、关联、分页和复合索引","link":"/middleware/mysql/base/intermediate/model"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"MySQL 建模与查询：约束、关联、分页和复合索引","link":"/middleware/mysql/base/intermediate/model"}},"headers":[],"relativePath":"middleware/mysql/base/basic/start.md","filePath":"middleware/mysql/base/basic/start.md"}'),l={name:"middleware/mysql/base/basic/start.md"};function t(h,s,k,p,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="mysql-起步与命令-sql-连接、建库和基本读写" tabindex="-1">MySQL 起步与命令 SQL：连接、建库和基本读写 <a class="header-anchor" href="#mysql-起步与命令-sql-连接、建库和基本读写" aria-label="Permalink to &quot;MySQL 起步与命令 SQL：连接、建库和基本读写&quot;">​</a></h1><p>本轮仅全文静态审计，未安装依赖、启动服务、连接数据库或执行任何示例。下文实测、RED/GREEN及平台结果均为此前历史证据；本轮修改后的脚本未运行，命令与输出作为学习步骤和预期保留。</p><h2 id="environment" tabindex="-1">版本、终端与实验边界 <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;版本、终端与实验边界 {#environment}&quot;">​</a></h2><p>MySQL是保存关系表并执行SQL的服务端；mysql是向服务端发请求的客户端。安装Python驱动不会安装数据库。前置只需会打开终端、切换目录和编辑文本；在仓库根目录执行本课程命令，SQL则在mysql提示符后执行，不把两种命令混输。</p><p>教学固定MySQL <strong>8.4.7 LTS</strong>、CPython <strong>3.12.14</strong>、官方Connector/Python <strong>9.5.0</strong>；这是可复现组合，不表示最新版本。核对日期2026-10-17。MySQL镜像为Linux/amd64；Windows通过Docker Desktop运行Linux服务，不能据此声称验证了Windows原生MySQL安装。项目客户端在Windows与Linux均实际运行；macOS不纳入。</p><p>需要Docker引擎已启动、端口23306空闲。以下PowerShell/Bash均可按单行执行，名称和密码只用于本地独立实验；已有同名容器时先检查，不覆盖用户数据库。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql:8.4.7</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4-mysql-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:23306:3306</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MYSQL_ROOT_PASSWORD=m4-local-root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MYSQL_DATABASE=inventory_lab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MYSQL_USER=lab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MYSQL_PASSWORD=m4-local-lab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4-mysql-data:/var/lib/mysql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql:8.4.7</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4-mysql-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysqladmin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -uroot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pm4-local-root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showdocs-m4-mysql-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --default-character-set=utf8mb4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ulab</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inventory_lab</span></span></code></pre></div><p>首次初始化可能尚未完成，mysqladmin失败时检查docker logs，等待就绪后重试；不要因此重建数据卷。首次SQL预期VERSION为8.4.7、DATABASE为inventory_lab、CURRENT_USER对应lab账号（Host按账号匹配决定）。</p><p>最后一步交互输入实验密码m4-local-lab；命令行-p后不接密码可避免出现在Shell历史。ping只证明服务接受连接，仍需验证实际账号和数据库。Docker环境变量只在空数据目录首次初始化时生效，修改-e不会重设已有volume密码。容器内mysql默认连Unix socket；宿主机驱动连127.0.0.1:23306，两个端口分别是容器3306与映射23306。</p><h2 id="sql" tabindex="-1">常用命令与安全读写 <a class="header-anchor" href="#sql" aria-label="Permalink to &quot;常用命令与安全读写 {#sql}&quot;">​</a></h2><p>下面每句以分号结束；<code>\\q</code>退出客户端，<code>\\c</code>取消当前未完成输入。SQL关键字大小写不影响含义；表名大小写可能随系统配置变化，本课程统一小写。</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CURRENT_USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW DATABASES;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW TABLES;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @@character_set_connection, @@transaction_isolation, @@autocommit;</span></span></code></pre></div><p>首次表列表为空是正常结果。先运行<a href="/middleware/mysql/plus/practice/application#run">完整项目初始化</a>，再在同一库试读写：</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">START TRANSACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stock</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ROW_COUNT();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ROLLBACK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>WHERE决定受影响行，UPDATE没有WHERE会更新全表。操作前用同一WHERE做SELECT预览并核对目标库。ROW_COUNT为上一语句影响行数；不要先执行其他语句再读取。ROLLBACK后库存不变；CREATE TABLE等DDL可能隐式提交，不能靠把DDL包进事务获得撤销功能。DROP/DELETE不是本课程初始化的通用清理办法。</p><h2 id="null" tabindex="-1">NULL、字符集与比较 <a class="header-anchor" href="#null" aria-label="Permalink to &quot;NULL、字符集与比较 {#null}&quot;">​</a></h2><p>NULL表示未知或未提供，空字符串表示已知的零长度字符串，二者不同。<code>note=NULL</code>的结果是UNKNOWN，WHERE只保留TRUE，因此用<code>IS NULL</code>。聚合COUNT(*)统计行，COUNT(note)只统计非NULL值。</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku,note,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COALESCE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(note,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;未填写&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> display_note </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(note) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> filled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> note </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>项目两个商品note都是NULL，因此total=2、filled=0。采用utf8mb4保存中文及四字节emoji，连接字符集也须相同，只有表定义正确仍可能在传输时损坏。sku与request_id使用utf8mb4_bin，使请求标识大小写区分；展示名的排序、大小写、重音规则需要按业务选择collation，不能把排序规则当作编码。</p><h2 id="connection" tabindex="-1">账号、连接与下一步 <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;账号、连接与下一步 {#connection}&quot;">​</a></h2><p>应用使用仅获inventory_lab权限的lab账号，不使用root。真实远程服务需限制网络与账号来源、通过密钥管理提供密码并核验TLS证书；本机隔离实验没有验收公网TLS部署。<code>Access denied</code>要同时核对账号、密码、来源Host和目标库，<code>Can&#39;t connect</code>则先核对进程、端口和网络。不要把修改认证插件当所有连接失败的通用解。</p><p>继续<a href="/middleware/mysql/base/intermediate/model#schema">建模与查询</a>，遇错误查看<a href="/middleware/mysql/plus/practice/operations#errors">诊断顺序</a>。</p><p>研究依据：<a href="https://dev.mysql.com/doc/refman/8.4/en/" target="_blank" rel="noopener noreferrer">MySQL 8.4手册</a>、<a href="https://dev.mysql.com/doc/connector-python/en/connector-python-versions.html" target="_blank" rel="noopener noreferrer">驱动兼容矩阵</a>。国内资料采用<a href="https://support.huaweicloud.com/bestpractice-rds-mysql/rds-mysql-bestpractice-pdf.pdf" target="_blank" rel="noopener noreferrer">华为云MySQL最佳实践</a>对照运维任务；云厂商特定内核功能不推定为社区版能力。</p><p>自检练习：<a href="/middleware/mysql/pro/review/review#exercises">NULL题1</a>。提示：逐行判断note是否参与计数；<a href="/middleware/mysql/pro/review/review#answers">解答</a>另列。</p>`,24)])])}const y=i(l,[["render",t]]);export{o as __pageData,y as default};
